  "aireplay": "//command: aireplay\ncryptools = include_lib(\"/lib/crypto.so\")\nif not cryptools then exit(\"Error: Missing crypto library\")\nif params.len != 4 or params[0] == \"-h\" or params[0] == \"--help\" or params[0] != \"-b\" or params[2] != \"-e\" then exit(command_info(\"aireplay_usage\"))\n\nbssid = params[1]\nessid = params[3]\nresult = cryptools.aireplay(bssid, essid)\nif typeof(result) == \"string\" then exit(result)\n",
  "airmon": "//command: airmon\ncryptools = include_lib(\"/lib/crypto.so\")\nif not cryptools then exit(\"Error: Missing crypto library\")\nif params.len > 0 and (params.len != 2 or params[0] == \"-h\" or params[0] == \"--help\") then exit(command_info(\"airmon_usage\"))\n\ncomputer = get_shell.host_computer\nformatOutput = \"Interface Chipset Monitor_Mode\\n\"\nif params.len == 0 then\texit(format_columns(formatOutput + computer.network_devices))\noption = params[0]\ndevice = params[1]\nif option != \"start\" and option != \"stop\" then exit(command_info(\"airmon_usage\"))\n\noutput = cryptools.airmon(option, device)\nif not output then exit(\"airmon: \" + device + \" not found\")\nif typeof(output) == \"string\" then exit(output)\nprint(format_columns(formatOutput + computer.network_devices))",
  "apt-get": "//command: apt-get\naptclient = include_lib(\"/lib/aptclient.so\")\nif not aptclient then\n    aptclient = include_lib(current_path + \"/aptclient.so\")\nend if\nif not aptclient then exit(\"Error: Missing aptclient.so library in the /lib path or the current folder\")\n\nPendingUpdating = function(folderPath)\n\tpendingUpdate = []\n\ttargetFolder = get_shell.host_computer.File(folderPath)\n\tif targetFolder != null then\n\t\tfiles = targetFolder.get_files\n\t\tfor itemFile in files\n\t\t\toutput = aptclient.check_upgrade(itemFile.path)\n\t\t\tif output == true then\n\t\t\t\tpendingUpdate.push(itemFile.name)\n\t\t\tend if\n\t\tend for\n\tend if\n\treturn pendingUpdate\nend function \n\nif params.len == 0 or params.len > 3 then exit(command_info(\"apt-get_usage\"))\naction = params[0]\nif action == \"update\" then\n    print(\"Updating package lists...\")\n\toutput = aptclient.update\n\tif output then print(output)\n\t\nelse if action == \"install\" then\n    print(\"Reading package lists...\")\n\tif params.len < 2 then exit(command_info(\"apt-get_usage\"))\n\tprint(\"Downloading \" + params[1])\n\tcustomPath = \"\"\n\tif params.len == 3 then customPath = params[2]\n\toutput = aptclient.install(params[1], customPath)\n\tif output == true then exit(params[1] + \" installed\")\n\tprint(output)\n\t\nelse if action == \"search\" then\n\tif params.len != 2 then exit(command_info(\"apt-get_usage\"))\n\tprint(aptclient.search(params[1]))\n\t\nelse if action == \"show\" then\n\tif params.len != 2 then exit(command_info(\"apt-get_usage\"))\n\tprint(aptclient.show(params[1]))\n\t\nelse if action == \"addrepo\" then\n\tif params.len < 2 or params.len > 3 then exit(command_info(\"apt-get_usage\"))\n    port = 1542\n    if params.len == 3 then port = params[2]\n\toutput = aptclient.add_repo(params[1], port)\n\tif output then exit(output)\n\tprint(\"Repository \" + params[1] + \" added succesfully.\\nLaunch apt with the update option to apply the changes\")\n\t\nelse if action == \"delrepo\" then\n   \tif params.len != 2 then exit(command_info(\"apt-get_usage\"))\n    output = aptclient.del_repo(params[1])\n    if output then exit(output)\n    print(\"Repository \" + params[1] + \" removed succesfully.\\nLaunch apt with the update option to apply the changes\")\n\t\nelse if action == \"upgrade\" then\n    print(\"Reading package lists...\")\n\t//upgrade all packages\n\tif params.len == 1 then\n\t\tpendingPackages = PendingUpdating(\"/lib\") + PendingUpdating(\"/bin\")\n\t\tif pendingPackages.len == 0 then exit(\"No updates needed\")\n\t\tprint(\"The following packages will be updated:\")\n\t\tpkgs = \"\"\n\t\tfor itemPackage in pendingPackages\n\t\t\tpkgs = pkgs + \" \" + itemPackage\n\t\tend for\n\t\tprint(pkgs)\n\t\toption = user_input(\"\\nDo you want to continue?(y/n): \")\n\t\tif option == \"y\" or option == \"yes\" then\n\t\t\tcounter = 0\n\t\t\tfor itemPackage in pendingPackages\n\t\t\t\toutput = aptclient.install(itemPackage)\n\t\t\t\tif output == true then\n\t\t\t\t\tcounter = counter + 1\n\t\t\t\telse if output then\n\t\t\t\t\tprint(output)\n\t\t\t\tend if\n\t\t\tend for\n\t\t\tprint(counter + \" packages updated\")\n\t\telse \n\t\t\texit(\"aborted\")\n\t\tend if\n\t\n\t//upgrade specific package\n\telse if params.len == 2 then\n\t\toutput = aptclient.check_upgrade(\"/lib/\" + params[1])\n\t\tif typeof(output) == \"string\" then \n\t\t\toutput = aptclient.check_upgrade(\"/bin/\" + params[1])\n\t\tend if\n\t\tif not output then exit(\"No updates needed\")\n\t\tif output == true then\n\t\t\tprint(\"The following package will be updated:\\n\" + params[1])\n\t\t\toption = user_input(\"\\nDo you want to continue?(y/n): \")\n\t\t\tif option == \"y\" or option == \"yes\" then\n\t\t\t\toutput = aptclient.install(params[1])\n\t\t\t\tif output == true then exit(params[1] + \" installed.\")\n\t\t\t\tprint(output)\t\t\t\t\n\t\t\telse \n\t\t\t\texit(\"aborted\")\n\t\t\tend if\n\t\telse \n\t\t\tprint(output)\n\t\tend if\n\tend if\n\t\nelse \n\tprint(command_info(\"apt-get_usage\"))\nend if",
  "bash": "Bash = function()\n    deviceName = get_shell.host_computer.get_name\n    promptCurrentFolder = deviceName + current_path + \"$\"\n    if (active_user == \"root\") then\n        promptCurrentFolder = deviceName + \":\" + current_path + \"#\"\n    else if (current_path.indexOf(home_dir) != null) then\n        promptCurrentFolder = deviceName + \":~\"+ current_path.replace(home_dir, \"\") +\"$\"\n    end if\n    \n\toutput = user_input(active_user + \"@\" + promptCurrentFolder + \" \", false, false, true)\n\tif(output.len == 0) then return\n\t\n\tlistCmd = output.trim.split(\" \")\n\tcommand = listCmd[0]\n\tshellArgs = \"\"\n\tif(listCmd.len > 1) then\n\t\tlistCmd.remove(0)\n\t\tshellArgs = listCmd.join\n\tend if\n\t\n\tif(command == \"exit\") then exit\n\tif(command == \"clear\") then \n\t    clear_screen\n\telse\n\t    cmdPath = GetFinalPath(command)\n\t    output = get_shell.launch(cmdPath, shellArgs)\n\t    if output and output != 1 then print(output)\n\tend if\nend function\n\nGetFinalPath = function(command)\n    paths = [current_path, \"/bin\", \"/usr/bin\"]\n\tfor i in range(0, paths.len - 1)\n\t    if i == 0 then\n\t\t    absPath = get_abs_path(command)\n\t\telse \n\t\t    absPath = paths[i] + \"/\" + command\n\t\tend if\n\t \tcmdFile = get_shell.host_computer.File(absPath)\n\t\tif (cmdFile != null) then return absPath\n\tend for\n\treturn command\nend function\n\nwhile(true)\n\tBash()\nend while",
  "build": "//command: build\nif params.len != 2 then\n\tprint(command_info(\"build_usage\"))\nelse\n\tpathSource = get_abs_path(params[0])\n\tprogramPath = get_abs_path(params[1])\n\n\tshell = get_shell\n\tcomputer = shell.host_computer\n\tfileSource = computer.File(pathSource)\n\tfolderDest = computer.File(programPath)\n\n\tif fileSource == null then exit(\"build: can't find \"+ pathSource)\n\tif folderDest == null then exit(\"build: can't find \" + programPath)\n\t\n\toutput = shell.build(fileSource.path, folderDest.path)\n\tif output.len == 0 then\n\t\tprint(\"build successful.\")\n\telse\n\t\tprint(output);\n\tend if\nend if\n",
